package com.practiq.service;
import com.practiq.common.ApiException; import java.io.*; import java.nio.file.*; import java.sql.ResultSet; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile;
@Service public class MediaService { final JdbcTemplate db; final String mount; public MediaService(JdbcTemplate db,@Value("${practiq.object-storage-mount-dir}")String mount){this.db=db;this.mount=mount;}
 private Map<String,Object> row(ResultSet r,int n)throws java.sql.SQLException{var x=new LinkedHashMap<String,Object>();var m=r.getMetaData();for(int i=1;i<=m.getColumnCount();i++)x.put(m.getColumnLabel(i),r.getObject(i));return x;} private void editableQuestion(long u,long q){if(db.queryForObject("select count(*) from bank_question_links b join user_bank_links l on l.bank_id=b.bank_id where b.question_id=? and l.user_id=? and l.is_owner",Integer.class,q,u)==0)throw ApiException.of(403,"FORBIDDEN","Question owner access required");} private void editableGroup(long u,long g){if(db.queryForObject("select count(*) from bank_group_links b join user_bank_links l on l.bank_id=b.bank_id where b.group_id=? and l.user_id=? and l.is_owner",Integer.class,g,u)==0)throw ApiException.of(403,"FORBIDDEN","Group owner access required");} private void owned(long u,long m){if(db.queryForObject("select count(*) from media_assets where id=? and created_by=?",Integer.class,m,u)==0)throw ApiException.of(403,"FORBIDDEN","Media owner access required");}
 @Transactional public Map<String,Object> upload(long user,MultipartFile file){if(file==null)throw ApiException.of(400,"FILE_REQUIRED","Upload file is required");byte[] b;try{b=file.getBytes();}catch(IOException e){throw ApiException.of(400,"INVALID_FILE_CONTENT","Could not read upload");}if(b.length==0)throw ApiException.of(400,"EMPTY_FILE","Upload file is empty");if(b.length>UploadSupport.MEDIA_MAX)throw ApiException.of(413,"FILE_TOO_LARGE","Media file exceeds 10 MiB");String name=Optional.ofNullable(file.getOriginalFilename()).orElse("").replace('\\','/');name=name.substring(name.lastIndexOf('/')+1);if(name.isBlank()||name.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>255)throw ApiException.of(400,"INVALID_FILE_NAME","Media file name must be 1-255 bytes");String mime=UploadSupport.imageMime(b);String ext=switch(mime){case "image/png"->".png";case "image/jpeg"->".jpg";case "image/gif"->".gif";case "image/webp"->".webp";default->throw ApiException.of(400,"UNSUPPORTED_FILE_TYPE","Only PNG, JPEG, GIF, and WebP images are supported");};String rel="media/"+user+"/"+UploadSupport.token()+ext;Path p=UploadSupport.path(mount,rel);try{Files.createDirectories(p.getParent());Files.write(p,b,StandardOpenOption.CREATE_NEW);}catch(IOException e){throw ApiException.of(500,"MEDIA_STORAGE_FAILED","Could not store media");}try{return db.query("insert into media_assets(created_by,storage_path,original_name,mime_type,size_bytes) values(?,?,?,?,?) returning id,created_by,external_url,original_name,mime_type,width,height,size_bytes,duration_ms,created_at",this::row,user,rel,name,mime,b.length).getFirst();}catch(RuntimeException e){try{Files.deleteIfExists(p);}catch(IOException ignored){}throw e;}}
 public Map<String,Object> asset(long u,String role,long id){var r=db.query("select id,created_by,storage_path,external_url,original_name,mime_type,width,height,size_bytes,duration_ms,created_at from media_assets where id=? and (created_by=? or ?='admin' or exists(select 1 from question_media_links l join bank_question_links b on b.question_id=l.question_id join question_banks k on k.id=b.bank_id left join user_bank_links x on x.bank_id=k.id and x.user_id=? where l.media_id=media_assets.id and (x.is_owner or ((k.is_public or x.id is not null) and b.status='active'))) or exists(select 1 from question_option_media_links l join question_options o on o.id=l.option_id join bank_question_links b on b.question_id=o.question_id join question_banks k on k.id=b.bank_id left join user_bank_links x on x.bank_id=k.id and x.user_id=? where l.media_id=media_assets.id and (x.is_owner or ((k.is_public or x.id is not null) and b.status='active')))) limit 1",this::row,id,u,role,u,u);if(r.isEmpty())throw ApiException.of(404,"NOT_FOUND","Media asset not found");var x=r.getFirst();x.put("content_url","/api/v1/media/"+id+"/content");x.remove("storage_path");return x;}
 public byte[] content(long u,String role,long id){asset(u,role,id);String rel=db.queryForObject("select storage_path from media_assets where id=?",String.class,id);try{return Files.readAllBytes(UploadSupport.path(mount,rel));}catch(NoSuchFileException e){throw ApiException.of(404,"MEDIA_CONTENT_NOT_FOUND","Media content not found");}catch(IOException e){throw ApiException.of(500,"MEDIA_STORAGE_FAILED","Could not read media");}}
 @Transactional public void delete(long u,String role,long id){if(!"admin".equals(role))throw ApiException.of(403,"ADMIN_REQUIRED","Administrator privileges required");var r=db.queryForList("delete from media_assets where id=? returning storage_path",id);if(r.isEmpty())throw ApiException.of(404,"NOT_FOUND","Media asset not found");try{Files.deleteIfExists(UploadSupport.path(mount,(String)r.getFirst().get("storage_path")));}catch(IOException ignored){}}
 @Transactional public Map<String,Object> link(long u,String type,long owner,long media,String kind,Integer order){if(kind==null||kind.trim().isEmpty()||kind.trim().length()>64)throw ApiException.of(422,"VALIDATION_ERROR","Invalid request");if(type.equals("question"))editableQuestion(u,owner);else if(type.equals("group"))editableGroup(u,owner);else {long q=db.queryForObject("select question_id from question_options where id=?",Long.class,owner);editableQuestion(u,q);}owned(u,media);String table=type.equals("question")?"question_media_links":type.equals("group")?"question_group_media_links":"question_option_media_links";String col=type.equals("question")?"question_id":type.equals("group")?"group_id":"option_id";int n=order==null?1:order;if(n<1||n>32767)throw ApiException.of(422,"VALIDATION_ERROR","Invalid request");return db.query("insert into "+table+"("+col+",media_id,media_kind,sort_order) values(?,?,?,?) returning *",this::row,owner,media,kind.trim(),n).getFirst();}
 @Transactional public void unlink(long u,String type,long owner,long media){if(type.equals("question"))editableQuestion(u,owner);else if(type.equals("group"))editableGroup(u,owner);else {long q=db.queryForObject("select question_id from question_options where id=?",Long.class,owner);editableQuestion(u,q);}String table=type.equals("question")?"question_media_links":type.equals("group")?"question_group_media_links":"question_option_media_links";String col=type.equals("question")?"question_id":type.equals("group")?"group_id":"option_id";if(db.update("delete from "+table+" where "+col+"=? and media_id=?",owner,media)==0)throw ApiException.of(404,"NOT_FOUND","Media link not found");}
}
